"use client";
import { useId, useRef, useState } from "react";
import "./command-palette.css";

export interface Command {
  id: string;
  label: string;
  group?: string;
  shortcut?: string;
  onSelect?: () => void;
}
/** A searchable command list: a real combobox with arrow keys, Enter, and live results. */
export function CommandPalette({
  commands,
  placeholder = "Type a command",
  emptyText = "No matching commands",
  className = "",
}: {
  commands: Command[];
  placeholder?: string;
  emptyText?: string;
  className?: string;
}) {
  const list = useId();
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [ran, setRan] = useState("");
  const scroller = useRef<HTMLUListElement>(null);
  const q = query.trim().toLowerCase();
  const results = commands.filter((c) => `${c.label} ${c.group ?? ""}`.toLowerCase().includes(q));
  const index = Math.min(active, Math.max(0, results.length - 1));
  const move = (next: number) => {
    setActive(next);
    scroller.current?.children[next]?.scrollIntoView({ block: "nearest" });
  };
  const run = (command?: Command) => {
    if (!command) return;
    command.onSelect?.();
    setRan(`Ran ${command.label}`);
  };
  return (
    <div className={`forme-command ${className}`}>
      <input
        role="combobox"
        aria-expanded="true"
        aria-controls={list}
        aria-activedescendant={results.length ? `${list}-${results[index].id}` : undefined}
        aria-label={placeholder}
        placeholder={placeholder}
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setActive(0);
        }}
        onKeyDown={(e) => {
          if (!results.length) return;
          if (e.key === "ArrowDown") {
            e.preventDefault();
            move((index + 1) % results.length);
          } else if (e.key === "ArrowUp") {
            e.preventDefault();
            move((index - 1 + results.length) % results.length);
          } else if (e.key === "Enter") {
            e.preventDefault();
            run(results[index]);
          }
        }}
      />
      <ul id={list} role="listbox" ref={scroller} aria-label="Commands">
        {results.map((c, i) => (
          <li
            key={c.id}
            id={`${list}-${c.id}`}
            role="option"
            aria-selected={i === index}
            onPointerMove={() => i !== index && setActive(i)}
            onClick={() => run(c)}
          >
            <span>{c.label}</span>
            {c.group && <small>{c.group}</small>}
            {c.shortcut && <kbd>{c.shortcut}</kbd>}
          </li>
        ))}
      </ul>
      {!results.length && <p className="forme-command-empty">{emptyText}</p>}
      <span className="forme-command-status" role="status">
        {ran}
      </span>
    </div>
  );
}

.forme-command {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  max-width: 460px;
  overflow: hidden;
  border-radius: 16px;
  background: linear-gradient(180deg, #17171b, #0e0e11);
  box-shadow:
    inset 0 0 0 1px #ffffff17,
    inset 0 1px 0 #ffffff14,
    0 30px 70px -24px #000000e6;
  color: #f4f4f5;
  font-size: 14px;
}
.forme-command input {
  box-sizing: border-box;
  width: 100%;
  height: 50px;
  padding: 0 18px;
  border: 0;
  border-bottom: 1px solid #ffffff12;
  outline: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-size: 15px;
}
.forme-command input::placeholder {
  color: #71717a;
}
.forme-command:has(input:focus-visible) {
  box-shadow:
    inset 0 0 0 1px #ffffff3d,
    inset 0 1px 0 #ffffff14,
    0 30px 70px -24px #000000e6;
}
.forme-command ul {
  max-height: 224px;
  margin: 0;
  padding: 6px;
  overflow: auto;
  list-style: none;
}
.forme-command li {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 38px;
  padding: 0 12px;
  border-radius: 9px;
  color: #a1a1aa;
  cursor: pointer;
}
.forme-command li[aria-selected="true"] {
  background: #ffffff0f;
  color: #f4f4f5;
}
.forme-command small {
  color: #71717a;
  font-size: 12px;
}
.forme-command kbd {
  margin-left: auto;
  padding: 2px 6px;
  border-radius: 5px;
  background: #ffffff0f;
  color: #a1a1aa;
  font: inherit;
  font-size: 11px;
}
.forme-command-empty {
  margin: 0;
  padding: 26px 18px;
  color: #71717a;
  text-align: center;
}
.forme-command-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  .forme-command li {
    transition: none;
  }
}
